contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        require(caller != address(0));
        address originalOwner = c.owner();
        bool callerIsOwner = (caller == originalOwner);
        bool reverted;
        bool success;

        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address finalOwner = c.owner();
        success = !reverted;

        assert(
            (callerIsOwner && success && finalOwner == newOwner) ||
            (!callerIsOwner && reverted && finalOwner == originalOwner)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        address originalOwner = c.owner();

        // Impose the precondition that the caller is not the current owner, so the rule is non-vacuous.
        require(caller != originalOwner);

        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address finalOwner = c.owner();

        assert(reverted && finalOwner == originalOwner);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address caller = msg.sender;
        address originalOwner = c.owner();
        require(caller == originalOwner);

        bool success;
        bool reverted;
        try c.setOwner(newOwner) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            success = false;
            reverted = true;
        }

        address finalOwner = c.owner();

        assert(!reverted && success && finalOwner == newOwner);
    }
}

